package org.dysseux.hrtf

import android.graphics.BitmapFactory
import org.json.JSONArray
import org.json.JSONObject
import org.junit.Assert.*
import org.junit.Test
import org.junit.runner.RunWith
import org.robolectric.RobolectricTestRunner
import org.robolectric.annotation.Config
import org.robolectric.annotation.GraphicsMode
import kotlin.math.abs

/** These fixtures are generated by the existing desktop SciPy/Pillow implementation. */
@RunWith(RobolectricTestRunner::class)
@Config(sdk = [33], manifest = Config.NONE)
@GraphicsMode(GraphicsMode.Mode.NATIVE)
class PipelineParityTest {
    private fun resource(name: String) = requireNotNull(javaClass.classLoader!!.getResourceAsStream("parity/$name")) {
        "Run tools/export_reference.py in the dedicated Android HRTF environment before testing."
    }
    private fun doubles(array: JSONArray) = DoubleArray(array.length()) { array.getDouble(it) }
    private fun floats(array: JSONArray) = FloatArray(array.length()) { array.getDouble(it).toFloat() }

    @Test fun kotlinSynthesisMatchesDesktopScipyIncludingRealVikingMagnitude() {
        val fixture = resource("acoustic_reference.json").bufferedReader().use { JSONObject(it.readText()) }
        val positions = fixture.getJSONArray("positions").let { arr -> Array(arr.length()) { doubles(arr.getJSONArray(it)) } }
        val base = fixture.getJSONArray("base").let { arr -> Array(arr.length()) { i -> Array(2) { doubles(arr.getJSONArray(i).getJSONArray(it)) } } }
        val left = fixture.getJSONArray("left").let { arr -> Array(arr.length()) { floats(arr.getJSONArray(it)) } }
        val right = fixture.getJSONArray("right").let { arr -> Array(arr.length()) { floats(arr.getJSONArray(it)) } }
        val expected = fixture.getJSONArray("expected")
        val actual = AcousticProcessor.synthesize(AcousticProcessor.Reference(positions, base, fixture.getInt("sample_rate")),
            left, right, fixture.getDouble("head_width"), fixture.getDouble("head_depth"))
        for (i in actual.indices) for (ear in 0..1) {
            val oracle = expected.getJSONArray(i).getJSONArray(ear)
            for (sample in 0 until oracle.length()) assertEquals("direction=$i ear=$ear sample=$sample",
                oracle.getDouble(sample), actual[i][ear][sample].toDouble(), 2e-6)
            for (sample in oracle.length() until actual[i][ear].size) assertEquals(0f, actual[i][ear][sample], 0f)
        }
    }

    @Test fun cropAndContoursMatchDesktopPhysicalScaleAndEdgePipeline() {
        val bitmap = resource("photo_input.png").use(BitmapFactory::decodeStream)
        val calibration = PhotoProcessor.Calibration(300.0, 300.0, 40.0, 20.0, 240.0, 20.0, 40.0)
        val pixels = IntArray(bitmap.width * bitmap.height)
        bitmap.getPixels(pixels, 0, bitmap.width, 0, 0, bitmap.width, bitmap.height)
        val actualGray = PhotoProcessor.calibratedGray(pixels, bitmap.width, bitmap.height, calibration)
        val grayBytes = resource("photo_gray.bin").use { it.readBytes() }
        val oracleGray = DoubleArray(grayBytes.size) { (grayBytes[it].toInt() and 255) / 255.0 }
        val cropMeanError = actualGray.indices.sumOf { abs(actualGray[it] - oracleGray[it]) * 255 } / actualGray.size
        assertTrue("Bicubic crop must match Pillow to within one intensity level: $cropMeanError", cropMeanError < 1.0)
        val expected = resource("photo_contours.bin").use { it.readBytes() }
        val fromExactGray = PhotoProcessor.contours(oracleGray, .15)
        val contourMeanError = fromExactGray.indices.sumOf { abs(fromExactGray[it] - (expected[it].toInt() and 255)).toDouble() } / expected.size
        assertTrue("Canny and antialiased Lanczos must match Pillow/SciPy: $contourMeanError", contourMeanError < 1.0)
        val output = PhotoProcessor.prepare(bitmap, calibration)
        assertEquals(256, output.width); assertEquals(256, output.height)
        val outputPixels = IntArray(256 * 256); output.getPixels(outputPixels, 0, 256, 0, 0, 256, 256)
        var intersection = 0; var countActual = 0; var countExpected = 0
        for (i in outputPixels.indices) {
            val a = (outputPixels[i] and 255) > 80; val b = (expected[i].toInt() and 255) > 80
            if (a) countActual++; if (b) countExpected++; if (a && b) intersection++
        }
        val dice = 2.0 * intersection / (countActual + countExpected)
        assertTrue("Complete photo preprocessing must preserve the desktop contours: Dice=$dice", dice > .9)
        output.recycle(); bitmap.recycle()
    }
}
